/**
 * #451 — the host-matrix workflow shipped calling scripts that do not exist.
 *
 * The 19-version real-legs sweep merged via #448 put a green table in the README under the
 * header "Regenerated by the version-sweep workflow". No such workflow had ever executed:
 * `gh workflow list` registered only CI/Pages/release (GitHub only schedules workflows that
 * exist on the DEFAULT branch, and host-matrix.yml lived only on staging), and as committed
 * the file was broken anyway — a find/replace pass had mangled `scripts/matrix-run.mts` into
 * `scripts/de-de-de.mjs`, the name/concurrency strings into `de-de`, and the result dirs into
 * `var/de-de-de`. The first step of a would-be run dies on `Cannot find module`. Nobody
 * noticed, because nothing on the repo plane checked that a workflow names a real file — the
 * exact class #386 (release-gate) and #393 (release-claims) already guard for release.yml.
 *
 * Rows below are workflow-plane guards of that precedent, plus one BEHAVIOUR row: the report
 * stamp is generated by running the real `matrix-run.mts` against a fixture runs dir, so the
 * plane-attribution fix is executed, not asserted by string match.
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync, readdirSync, existsSync, mkdtempSync, writeFileSync, rmSync, mkdirSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { tmpdir } from 'node:os'

const ROOT = fileURLToPath(new URL('../..', import.meta.url))
const WF_DIR = join(ROOT, '.github', 'workflows')
const wfPath = join(WF_DIR, 'host-matrix.yml')
const wf = readFileSync(wfPath, 'utf8')
const readme = readFileSync(join(ROOT, 'README.md'), 'utf8')

/** Parse YAML with PyYAML — the same parser ci.yml's "workflow files parse" step uses (see
 *  the long reason in release-gate.test.ts: a stray Node `yaml` package once made every
 *  row pass vacuously off-machine, and python is already a build-time requirement here). */
function parseWorkflow(path: string): Record<string, any> {
  const py = [
    'import json, sys, yaml',
    'd = yaml.safe_load(open(sys.argv[1]))',
    'def fix(x):',
    '    if isinstance(x, dict):',
    '        return {("on" if k is True else "off" if k is False else k): fix(v) for k, v in x.items()}',
    '    if isinstance(x, list):',
    '        return [fix(i) for i in x]',
    '    return x',
    'print(json.dumps(fix(d)))',
  ].join('\n')
  return JSON.parse(execFileSync('python3', ['-c', py, path], { encoding: 'utf8' }))
}

const scriptRefRe = /scripts\/[A-Za-z0-9_][A-Za-z0-9_.\/-]*\.(?:mjs|cjs|js|mts|cts|ts|sh|py)/g

/** Every scripts/<file> reference in every workflow under dir, unresolved against dir/../..
 *  (for a fixture dir, unresolved against the fixture's own sibling scripts/ if present). */
function unresolvedScriptRefs(dir: string, base = ROOT): string[] {
  const bad: string[] = []
  for (const f of readdirSync(dir).filter((x) => /\.(yml|yaml)$/.test(x))) {
    for (const m of readFileSync(join(dir, f), 'utf8').matchAll(scriptRefRe)) {
      if (!existsSync(join(base, m[0]))) bad.push(`${f}: ${m[0]}`)
    }
  }
  return bad
}

test('#454/#455: the compose plane is a DEFAULT leg, the evidence is committed, the enumeration is checked', () => {
  const doc = parseWorkflow(wfPath)
  assert.equal(doc.on.workflow_dispatch.inputs.legs.default, 'unit+integration+compose',
    'suite-green must never stand alone in the nightly — compose rides by default (#454)')
  const reportRun = (doc.jobs.report.steps ?? []).flatMap((s: any) => String(s.run ?? '').split('\n')).join('\n')
  assert.match(reportRun, /--enumerated=var\/matrix\.json/, 'unverified enumerated versions ride the table as named gaps (#455)')
  assert.match(reportRun, /mkdir -p matrix-verdicts/, 'verdicts are committed alongside the table (#455)')
  assert.match(reportRun, /git add README\.md matrix-verdicts/, 'the refresh PR carries the receipts, not just the prose')
  assert.match(wf, /result-\$\{\{ matrix\.version \}\}\.json\.lock\.json/, 'the RESOLVED lock is uploaded beside the verdict (#455)')
})

test('#455: the liveness sentinel lives in the REGISTERED CI workflow and only runs on its timer', () => {
  const ci = parseWorkflow(join(WF_DIR, 'ci.yml'))
  assert.ok(ci.on.schedule !== undefined, 'ci.yml carries a schedule — the sentinel must be in a registered workflow')
  const job = ci.jobs?.['nightly-liveness']
  assert.ok(job !== undefined, 'the sentinel job exists')
  assert.equal(job.if, "github.event_name == 'schedule'", 'and fires only on the timer')
  const raw = readFileSync(join(WF_DIR, 'ci.yml'), 'utf8')
  assert.match(raw, /scripts\/nightly-liveness\.mjs/, 'it runs the tested script')
  // the heavy jobs must opt OUT of schedule events, or every 04:47 would re-run the full chain
  for (const name of ['test', 'host-capability', 'e2e-replay', 'environment-parity']) {
    assert.match(String(ci.jobs[name]?.if ?? ''), /github\.event_name != 'schedule'/, `${name} skips schedule events`)
  }
})

test('#451: every scripts/<file> reference in EVERY workflow resolves to a real file', () => {
  // This is the row whose absence let #451 ship: host-matrix.yml called
  // scripts/de-de-de.mjs, which never existed.
  assert.deepEqual(unresolvedScriptRefs(WF_DIR), [],
    'a workflow that names a missing script is a workflow that cannot run')
})

test('#451: the guard itself is not vacuous — a mangled reference turns it red (mutation proof)', () => {
  const dir = mkdtempSync(join(tmpdir(), 'wfscan-'))
  try {
    writeFileSync(join(dir, 'evil.yml'), 'jobs:\n  a:\n    steps:\n      - run: node scripts/de-de-de.mjs --version=X\n')
    const caught = unresolvedScriptRefs(dir)
    assert.equal(caught.length, 1, `the fixture's broken ref must be found: ${JSON.stringify(caught)}`)
    assert.match(caught[0]!, /evil\.yml: scripts\/de-de-de\.mjs/)
  } finally { rmSync(dir, { recursive: true, force: true }) }
})

test('#451: no workflow carries mangled placeholder tokens — the exact corruption class', () => {
  // The find/replace pass that ate matrix-run.mts also rewrote the workflow NAME and the
  // result directories. A token scan guards the symptom family, in comments too: a comment
  // naming a dead script is a roadmap back into the same hole.
  for (const f of readdirSync(WF_DIR).filter((x) => /\.(yml|yaml)$/.test(x))) {
    const src = readFileSync(join(WF_DIR, f), 'utf8')
    const hits = ['de-de', 'REPLACED'].filter((t) => src.includes(t))
    assert.deepEqual(hits, [], `${f} contains mangled placeholder token(s): ${hits.join(', ')}`)
  }
})

test('#451: host-matrix identity is coherent — file, name, concurrency, refresh branch, README citation', () => {
  const doc = parseWorkflow(wfPath)
  assert.ok(typeof doc.name === 'string' && doc.name.length > 0, 'the workflow has a real display name')
  assert.equal(doc.concurrency?.group, 'host-matrix', 'the concurrency group names this workflow, not a mangled token')
  assert.match(wf, /BR="chore\/refresh-/, 'the refresh job branches under chore/refresh-')
  assert.match(readme, /host-matrix\.yml/, 'the README cites the workflow file that actually exists')
  assert.match(readme, /scripts\/matrix-run\.mts/, 'and cites the runner that actually exists')
})

test('#451: the pipeline paths agree across jobs — matrix-run.mts, var/matrix-runs, and var/ is created before use', () => {
  const doc = parseWorkflow(wfPath)
  const runs = (job: string): string[] => (doc.jobs[job]?.steps ?? [])
    .flatMap((s: any) => String(s.run ?? '').split('\n'))
  const listRun = runs('list').join('\n')
  const mkdir = listRun.indexOf('mkdir -p var')
  const write = listRun.indexOf('> var/matrix.json')
  assert.ok(mkdir >= 0 && mkdir < write,
    'var/ is gitignored — a clean checkout has no var/, so the redirect must come AFTER mkdir (latent crash #451 found before it could fire)')
  assert.ok(/scripts\/matrix-run\.mts/.test(listRun), 'the list job runs the real matrix runner')
  const cellDirs = new Set<string>()
  for (const line of [...runs('test'), ...runs('report')]) {
    const m = line.match(/(?:--out=|--runs=|path: |with: \{ pattern: 'result-\*', path: )((?:var|\/)[A-Za-z0-9_./-]*?)\s*(?:\}|$)/)
    if (m?.[1] !== undefined) cellDirs.add(m[1].replace(/\/result-.*$/, '').replace(/\/$/, ''))
  }
  for (const d of cellDirs) {
    if (d.startsWith('var/')) assert.equal(d, 'var/matrix-runs', `cell dir ${d} must be the one the runner defaults to`)
  }
})

test('#451: the report stamp names the plane that EXECUTED — run the real generator on fixtures', () => {
  // Behaviour, not string-matching: the 15:29 table claimed a workflow that had never run.
  // Default = honest local wording; --source= lets CI name itself; neither is fabricated here.
  const dir = mkdtempSync(join(tmpdir(), 'mreport-'))
  try {
    const runsDir = join(dir, 'runs')
    mkdirSync(runsDir)
    for (const v of ['0.2.0-rc.1', '0.2.2-rc.5']) {
      writeFileSync(join(runsDir, `result-${v}.json`), JSON.stringify({
        version: v, swap: { ok: true, detail: 'fixture' },
        legs: [{ leg: 'unit', ok: true, ms: 1, detail: 'pass 1 / fail 0 / todo 0' }],
        verdict: 'pass', ts: '2026-11-20T00:00:00.000Z',
      }))
    }
    const md = join(dir, 'README.md')
    writeFileSync(md, 'x\n<!-- versions:begin -->\nold\n<!-- versions:end -->\ny\n')
    const strip = ['--experimental-strip-types', '--no-warnings', join(ROOT, 'scripts', 'matrix-run.mts')]
    execFileSync(process.execPath, [...strip, '--report', `--readme=${md}`, `--runs=${runsDir}`])
    const local = readFileSync(md, 'utf8')
    assert.match(local, /a local version-sweep run/, 'with no --source the stamp says LOCAL')
    assert.ok(!/GitHub Actions/.test(local), 'a local run must not claim the Actions workflow — that was the false attribution')
    assert.match(local, /\| 0\.2\.0-rc\.1 \| ✅ supported \| unit:✅/, 'the table itself comes from the artifacts')
    execFileSync(process.execPath, [...strip, '--report', `--readme=${md}`, `--runs=${runsDir}`,
      '--source=the host-matrix GitHub Actions workflow'])
    assert.match(readFileSync(md, 'utf8'), /GitHub Actions workflow/, 'and --source lets the CI report name itself truthfully')
  } finally { rmSync(dir, { recursive: true, force: true }) }
})
